{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "FormLayout",
    "displayName": "Form Layout",
    "group": "Layout",
    "category": "Layout",
    "keywords": [
      "formlayout",
      "form",
      "fieldset",
      "formgroup",
      "formcontainer",
      "fields",
      "vertical",
      "horizontal"
    ],
    "props": [
      {
        "name": "direction",
        "type": "'vertical' | 'horizontal' | 'horizontal-labels'",
        "description": "Controls field arrangement. Vertical stacks top-to-bottom, horizontal uses one fractional grid track per field in logical inline order, and horizontal-labels uses CSS Grid with labels beside inputs on the inline-start side (collapsing to vertical when the viewport is <=480px).",
        "default": "'vertical'"
      },
      {
        "name": "defaultOptionality",
        "type": "'optional' | 'required'",
        "description": "The state the form treats as its default, so only the exception shows an optional/required indicator. With \"optional\", only fields marked isRequired show an indicator; with \"required\", only fields marked isOptional do. A field that restates the default shows nothing. Under \"required\" the unmarked fields also expose aria-required so screen readers match the visual default; aria-required only, never the native required attribute. CheckboxInput, Switch and CheckboxList are the exception: an unchecked box, an off switch or an empty group is an answer, so they take no required state from the default. A CheckboxInput or Switch is required only through its own isRequired. Leave unset for today's per-field behavior."
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "Form fields to arrange. Accepts Astryx inputs (TextInput, Selector, etc.) and Field-wrapped custom controls."
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-form-layout",
          "visualProps": [
            "direction"
          ]
        }
      ]
    },
    "usage": {
      "description": "A layout container that arranges form fields with consistent spacing and direction. FormLayout handles where fields go, not state or submission. Wrap it in a native <form> for that; <form> has no Astryx replacement, so it stays a plain element. Supports vertical (default), horizontal, and horizontal-labels directions, and can be nested to mix them.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Stack fields vertically for most forms. It's the easiest to scan top to bottom."
        },
        {
          "guidance": true,
          "description": "Nest a horizontal FormLayout inside a vertical one when fields naturally pair up, like First Name + Last Name or City + State + ZIP."
        },
        {
          "guidance": true,
          "description": "Use horizontal-labels for settings pages where labels sit beside their inputs."
        },
        {
          "guidance": false,
          "description": "Use FormLayout for form state or submission. It's just layout. Wrap it in a native <form> for that."
        },
        {
          "guidance": false,
          "description": "Put unrelated fields side by side in a horizontal layout. Save it for fields that belong together."
        },
        {
          "guidance": false,
          "description": "Nest horizontal-labels inside another FormLayout. It uses CSS Grid and needs to be the outermost container."
        }
      ],
      "anatomy": [
        {
          "name": "Layout container",
          "required": true,
          "description": "Owns field arrangement, spacing, direction, and form-level optionality."
        },
        {
          "name": "Form title",
          "required": false,
          "description": "Heading that describes the purpose of the form."
        },
        {
          "name": "Fields",
          "required": true,
          "description": "Input components with labels for collecting user data."
        },
        {
          "name": "Footer",
          "required": false,
          "description": "Contains confirmation buttons such as Submit or Cancel."
        }
      ]
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/FormLayout",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
